#define main base_search_main
#include "search.cpp"
#undef main
struct Part {State entries;double x=0,y=0,radius=0;};
vector<Part>components(Graph&g,const State&s){map<int,int>left(s.begin(),s.end());vector<Part>parts;while(!left.empty()){Part p;vector<int>q{left.begin()->first};p.entries.push_back(*left.begin());left.erase(left.begin());for(size_t h=0;h<q.size();h++)for(int v:g.adj[q[h]]){auto it=left.find(v);if(it!=left.end()){q.push_back(v);p.entries.push_back(*it);left.erase(it);}}for(auto[c,v]:p.entries){p.x+=g.x[c];p.y+=g.y[c];}p.x/=p.entries.size();p.y/=p.entries.size();for(auto[c,v]:p.entries)p.radius=max(p.radius,hypot(g.x[c]-p.x,g.y[c]-p.y));parts.push_back(p);}return parts;}
int main(int argc,char**argv){if(argc<5){cerr<<"graph output trials seed\n";return 2;}Graph g(argv[1]);Engine engine(g);ofstream out(argv[2]);int trials=stoi(argv[3]);RNG random{stoull(argv[4])};vector<int>starts;for(int c=0;c<g.n;c++)if(hypot(g.x[c],g.y[c])<32&&g.bound[c]>=60)starts.push_back(c);map<string,double>best;map<string,int>outcomes;uint64_t qualifying=0;for(int trial=0;trial<trials;trial++){int C=4+random.n(7);int B=1<<2;int S=0;if(trial%4==1)B|=1<<(4+random.n(4));if(trial%4==2)S=1<<(4+random.n(3));if(trial%4==3){B|=1<<(4+random.n(4));S=1<<(4+random.n(3));}State init=soup(g,random,starts,C);if(random.n(2)==0)for(auto&v:init)v.second=1;Result r=engine.run(init,B,S,C,110,1500,140);outcomes[r.outcome]++;if(r.outcome=="horizon" &&r.minBoundary>=5){auto parts=components(g,r.final);bool good=parts.size()>=2&&parts.size()<=6;double maxRad=0,minTravel=1e9;double ix=0,iy=0;for(auto[c,v]:init){ix+=g.x[c];iy+=g.y[c];}ix/=init.size();iy/=init.size();for(auto&p:parts){if(p.entries.size()<5||p.entries.size()>50||p.radius>7)good=false;maxRad=max(maxRad,p.radius);minTravel=min(minTravel,hypot(p.x-ix,p.y-iy));}if(minTravel<60)good=false;if(good){qualifying++;string key=to_string(C)+"/"+to_string(parts.size());double score=1000-init.size()*3-r.final.size()*0.5-r.maxRadius*0.02;if(!best.count(key)||score>best[key]){best[key]=score;emit(out,r,B,S,C,parts.size(),trial,argv[1]);out.flush();cerr<<"HIT "<<trial<<" C="<<C<<" parts="<<parts.size()<<" seed="<<init.size()<<" final="<<r.final.size()<<" minTravel="<<minTravel<<"\n";}}}if(trial%1000==999)cerr<<trial+1<<"/"<<trials<<" steps="<<engine.totalSteps<<" qualifying="<<qualifying<<"\n";}cerr<<"COMPLETE trials="<<trials<<" steps="<<engine.totalSteps<<" qualifying="<<qualifying<<"\n";for(auto&[k,v]:outcomes)cerr<<k<<' '<<v<<'\n';}
